class FaqEntry {
  final String id;
  final String question;
  final String answer;
  const FaqEntry(this.id, this.question, this.answer);
}

class FaqCategory {
  final String id;
  final String label;
  final List<FaqEntry> items;
  const FaqCategory(this.id, this.label, this.items);
}

const faqUpdated = '2026-10-27';

const faqCategories = [
  FaqCategory('basics', 'Getting started', [
    FaqEntry('what-is-greenrev', 'What is GreenRev?', 'GreenRev is an automotive marketplace where you can discover cars, find automotive parts and connect with mechanics and other automotive businesses. It brings listings and provider information together to help you decide who to contact.'),
    FaqEntry('who-operates-greenrev', 'Who operates GreenRev?', 'GreenRev is operated by GreenCrest Ltd, a Nigerian company. For questions about the platform or your account, contact support@greenrevs.com.'),
    FaqEntry('who-can-use', 'Who can use GreenRev?', 'GreenRev serves people looking for vehicles, parts or automotive services, alongside dealers, parts vendors and mechanics. If you act for a business, you must have authority to represent it and enter any agreement you make.'),
    FaqEntry('where-greenrev-operates', 'Where does GreenRev operate?', 'GreenRev\'s initial marketplace focuses on Nigeria. The listings and providers you can find depend on the businesses currently available in each location. Confirm the seller\'s location and any collection or delivery arrangements before committing.'),
    FaqEntry('does-greenrev-own-cars', 'Does GreenRev own the cars and parts listed?', 'Marketplace listings are generally offered by independent sellers and businesses. Check the seller named on each listing. A listing on GreenRev does not mean GreenRev owns the item or is the party selling it to you.'),
    FaqEntry('browse-without-account', 'Can I browse before creating an account?', 'You can explore the public pages and listings. If an action requires an account, GreenRev will ask you to sign in or register at that point.'),
    FaqEntry('free-to-browse', 'Is GreenRev free for buyers to browse?', 'Browsing the marketplace is free. The vehicle, part or service you choose has its own price, and any inspection, delivery or other extra cost should be agreed before you proceed.'),
    FaqEntry('how-to-start', 'How do I get started?', 'Choose vehicles, parts or experts, then review the listings that suit your needs. Check the details and location, use the contact option shown, and ask the seller or provider any questions before arranging a visit, purchase or service.'),
    FaqEntry('outside-nigeria', 'Can I enquire from outside Nigeria?', 'You can contact a listed business from abroad, but confirm whether it can support your request. Arrange a trusted local inspection and verify the item, seller and documents before sending money. Shipping or export arrangements must be agreed separately.'),
    FaqEntry('contact-greenrev', 'How can I contact GreenRev support?', 'Email support@greenrevs.com. Include the listing link, the email or phone number linked to your account, a short description of the issue and any useful screenshots. Do not send your password, one-time codes or complete payment-card details.'),
  ]),
  FaqCategory('accounts', 'Accounts and access', [
    FaqEntry('create-account', 'How do I create an account?', 'Open the sign-up option on GreenRev and follow the steps shown. Enter accurate contact information, choose the account type that matches your use, and complete any verification prompts before submitting.'),
    FaqEntry('choose-account-type', 'Which account type should I choose?', 'Choose a customer account if you are exploring the marketplace for yourself. If you sell vehicles, supply parts or offer automotive services, choose the relevant business option shown during registration. Contact support if none matches your business.'),
    FaqEntry('verification-code', 'What should I do if a verification code does not arrive?', 'Check that your email address or phone number is correct, then check your spam folder or mobile signal. Use the resend option if one is offered. If the problem continues, contact support with the contact detail you used, without sharing any code you later receive.'),
    FaqEntry('forgot-password', 'What if I forget my password?', 'Use the password-reset option on the sign-in page and follow the instructions sent to your registered contact address. If you cannot access that address or cannot find the reset option, contact support for help with account recovery.'),
    FaqEntry('change-details', 'How do I update my contact or business details?', 'Use the profile or account settings available after signing in. If a detail cannot be edited, contact support from your registered account and explain the change. Important business or ownership changes may require additional checks.'),
    FaqEntry('multiple-businesses', 'Can I list more than one business or branch?', 'Contact support with the businesses or branches you want to list. Keep each location, service area and contact person clear so customers can identify the right branch. Confirm any package limits or separate account requirements before adding them.'),
    FaqEntry('staff-access', 'Can my staff manage listings for me?', 'Use staff or role-based access only if that option is available in your account. Otherwise, ask support how to manage authorised access. Avoid sharing passwords or one-time codes with a whole team.'),
    FaqEntry('business-approval', 'Why is my business account or listing awaiting review?', 'Some submissions may need a review or more information before they appear publicly. Check for a message asking you to correct details or provide evidence. Contact support with your business name or listing link if you need an update.'),
    FaqEntry('account-restricted', 'Why has my account been restricted?', 'An account may be restricted while a safety concern, disputed information or a possible breach of platform rules is reviewed. Read any notice you received and contact support with your account details and relevant evidence if you believe the decision is incorrect.'),
    FaqEntry('delete-account', 'How do I request account closure?', 'Use an account-closure option if one is available, or email support@greenrevs.com from your registered address. Ask separately about any active paid package, because closing an account and cancelling a billing arrangement may involve different steps. Relevant records may need to be retained as explained in the Privacy Policy.'),
  ]),
  FaqCategory('discover', 'Finding and comparing cars', [
    FaqEntry('find-car', 'How do I find a car on GreenRev?', 'Open the vehicle showroom, browse the available listings and use the search or filters shown. Open a listing to review its price, location, photographs, description and seller contact details.'),
    FaqEntry('search-no-results', 'Why am I not finding a car that matches my search?', 'Try a broader budget, a nearby location or fewer filters. Listings depend on current seller inventory, so a particular model may not be available. You can also ask a listed dealer whether it has a suitable alternative.'),
    FaqEntry('compare-two-cars', 'How do I compare two cars?', 'Use the comparison option to choose two available vehicles and review the information side by side. Compare the asking prices, specifications and listing details, then confirm any important difference with the sellers.'),
    FaqEntry('comparison-advice', 'Can I rely only on a comparison or AI-generated answer?', 'Use comparison information as a starting point. Listing errors, missing information and differences between vehicle variants can affect the result. Confirm important specifications with the seller and use an independent inspection before making a purchase decision.'),
    FaqEntry('listing-price-final', 'Is the advertised price the final price?', 'It is the seller\'s advertised asking price. Ask whether negotiation is possible and whether the price includes any taxes, documentation, inspection, registration or delivery charges. Get the agreed total in writing before paying.'),
    FaqEntry('vehicle-condition-labels', 'What do labels such as new, foreign-used or Nigerian-used mean?', 'These are seller descriptions of the vehicle\'s condition or use history. Ask the seller to explain the label and provide supporting documents. A condition label alone does not establish mileage, accident history, ownership or mechanical condition.'),
    FaqEntry('actual-photos', 'Are the photos of the actual vehicle?', 'Ask the seller to confirm that the photographs show the vehicle being offered. Request recent images, a video or a physical viewing if you need more detail. Images alone cannot confirm the vehicle\'s condition or that it is available.'),
    FaqEntry('vehicle-mileage', 'Is the mileage shown independently verified?', 'Treat mileage as listing information unless a specific independent check and its source are clearly identified. Compare the odometer reading with available service records and an independent inspection. Ask about any inconsistency before proceeding.'),
    FaqEntry('vehicle-availability', 'How do I confirm that a listed car is still available?', 'Contact the seller before travelling, arranging an inspection or making a payment. Ask the seller to confirm the exact vehicle, current price and viewing location. Report a listing that remains advertised after you are told it is unavailable.'),
    FaqEntry('save-share-listing', 'How can I save or share a vehicle I like?', 'Use a save or share option if it appears on the listing. You can also bookmark the page or copy its link. Recheck the listing and contact the seller before acting, because price and availability can change.'),
  ]),
  FaqCategory('buying', 'Buying a car', [
    FaqEntry('contact-seller', 'How do I contact a vehicle seller?', 'Open the listing and use the contact options displayed for that seller. Identify the vehicle you are asking about and confirm its availability, price, location and inspection arrangements. Keep a record of the conversation.'),
    FaqEntry('whatsapp-contact', 'Can I contact a seller through WhatsApp or by phone?', 'Use the phone or WhatsApp option if the seller has made it available on the listing. Keep the listing link and any conversation records so you can refer to the same vehicle and agreed terms later.'),
    FaqEntry('arrange-viewing', 'How do I arrange a viewing?', 'Agree a time and location directly with the seller. Confirm the exact vehicle and who will meet you. Prefer a suitable business premises or a safe location, and let someone you trust know where you are going.'),
    FaqEntry('bring-mechanic', 'Can I bring my own mechanic to an inspection?', 'Ask the seller to agree to an independent inspection before you travel. Bringing a mechanic you trust can help you assess the vehicle. Confirm the inspection fee and the checks to be performed directly with that mechanic.'),
    FaqEntry('test-drive', 'Can I test-drive a listed vehicle?', 'Agree this with the seller in advance. Confirm the licence, insurance, supervision and other conditions that apply. Do not drive a vehicle unless you are permitted and appropriately covered to do so.'),
    FaqEntry('vehicle-documents', 'What documents should I check before buying?', 'Ask for evidence of the seller\'s authority to sell, the vehicle identity and ownership, and relevant registration and import documents. Check that identifying details match the vehicle. The documents needed vary by transaction, so seek appropriate professional help if anything is unclear.'),
    FaqEntry('vin-check', 'Why should I check the VIN or chassis number?', 'The VIN or chassis number helps identify the exact vehicle. Compare the number physically on the vehicle with the documents provided. An inconsistency or sign of alteration should be resolved before you proceed; matching numbers alone do not prove a clean history.'),
    FaqEntry('negotiate-price', 'Can I negotiate the asking price?', 'You can ask the seller whether the price is negotiable. Agree any final price and extra charges directly, then obtain written confirmation identifying the exact vehicle before making payment.'),
    FaqEntry('reserve-car', 'Can I reserve a vehicle with a deposit?', 'A reservation is a separate arrangement with the seller. Before paying, verify the seller and vehicle and obtain written terms covering the amount, reservation period and when the deposit is refundable. GreenRev does not hold reservation deposits or provide escrow at launch.'),
    FaqEntry('receipt-handover', 'What should I collect when the vehicle is handed over?', 'Obtain a signed receipt or sale agreement identifying the vehicle, buyer, seller, price and date. Collect the agreed documents, keys and accessories, and record any outstanding obligations. Arrange the relevant ownership or registration updates with the appropriate authority or adviser.'),
  ]),
  FaqCategory('selling', 'Dealers and sellers', [
    FaqEntry('join-as-dealer', 'How do I join GreenRev as a dealer or seller?', 'Use the relevant business registration option on GreenRev and provide accurate business and contact details. Complete the steps shown before creating listings. Contact support if you need help choosing the right account for your business.'),
    FaqEntry('private-seller', 'Can a private owner sell a car on GreenRev?', 'Use a private-seller option if it is available in the registration or listing flow. If you only see business accounts, contact support before registering. You must own the vehicle or have the owner\'s authority to advertise it.'),
    FaqEntry('listing-information', 'What information should I include in a vehicle listing?', 'Include the correct make, model, year, price, location, mileage, condition and useful specifications. Add clear current photographs and disclose known material issues. Explain what is included in the price and how a buyer can arrange an inspection.'),
    FaqEntry('listing-photos', 'What makes a good set of listing photos?', 'Use clear photographs of the actual vehicle, including the exterior, interior and dashboard. Show relevant defects honestly and avoid misleading edits. Keep personal documents, private contact information and unrelated people out of the images.'),
    FaqEntry('list-on-behalf', 'Can I list a vehicle on behalf of an owner or another dealer?', 'Only advertise a vehicle if you have permission and can explain your role. Be clear about who owns it, who will receive payment and who can complete the sale. Do not claim ownership or business affiliation you cannot support.'),
    FaqEntry('listing-not-visible', 'Why is my listing not appearing?', 'Check whether it is saved as a draft, awaiting review, unavailable or missing required information. Review any account notice or package limit shown. Contact support with the listing reference or title if you cannot identify the problem.'),
    FaqEntry('edit-listing', 'How do I edit a price or correct a listing?', 'Open your listing-management area and use the available edit controls. Keep the price, description and availability accurate, and tell buyers about any change affecting an existing enquiry. If you cannot make a correction, contact support with the listing link.'),
    FaqEntry('sold-car', 'What should I do when a vehicle sells?', 'Mark it sold or remove it using the controls available in your account. If that is not possible, ask support to update the listing. Tell anyone with an active enquiry that the vehicle is no longer available.'),
    FaqEntry('respond-to-enquiries', 'How should I handle buyer enquiries?', 'Respond with clear information about the exact listing, current price and next steps. Confirm viewing arrangements and answer questions honestly. Keep a record of offers and agreements, and avoid requesting unnecessary personal documents from a buyer.'),
    FaqEntry('seller-outcomes', 'Does listing on GreenRev guarantee a sale or a number of leads?', 'A listing gives your business a place to be discovered, but it does not guarantee enquiries or a sale. Results depend on demand, price, location, listing quality and how you respond. Any specific paid campaign commitment must be stated in its written offer.'),
  ]),
  FaqCategory('parts', 'Car parts and accessories', [
    FaqEntry('find-parts', 'How do I find a car part?', 'Browse the parts section and review the listings that match your vehicle or the part you need. Contact the vendor with your vehicle details and, where possible, the exact part number before agreeing a purchase.'),
    FaqEntry('part-compatibility', 'How do I know a part will fit my car?', 'Confirm compatibility using the part number and your vehicle\'s exact model, year, engine and variant. Ask the vendor or a qualified mechanic to check before buying. Similar-looking parts can have different specifications.'),
    FaqEntry('part-condition', 'Are listed parts new, used or refurbished?', 'Check the description and ask the vendor to confirm the condition in writing. Ask about wear, previous repairs, included components and any test results relevant to the part. Do not assume a photograph or low price explains its condition.'),
    FaqEntry('genuine-parts', 'Are all parts guaranteed to be genuine?', 'A marketplace listing does not establish authenticity. Ask for the brand, part number, source and supporting evidence. If a part appears counterfeit or misrepresented, avoid proceeding and report the listing to support.'),
    FaqEntry('order-parts', 'How do I buy a listed part at launch?', 'Contact the vendor to confirm stock, compatibility, the total price and collection or delivery terms. Purchases are arranged with the vendor at launch. GreenRev does not provide integrated parts checkout, escrow or automatic payment protection in this release.'),
    FaqEntry('parts-delivery', 'Can a vendor deliver a part to me?', 'Ask the vendor whether delivery is available to your location. Agree the delivery charge, expected timing, carrier and responsibility for loss or damage before paying. Delivery is not automatically included in the advertised part price.'),
    FaqEntry('part-warranty', 'Do parts come with a warranty?', 'Ask the vendor what warranty, if any, applies to the exact part and get the terms in writing. Check the duration, exclusions, proof of purchase and claim process. A listing on GreenRev does not itself create an additional GreenRev product warranty.'),
    FaqEntry('part-installation', 'Is installation included when I buy a part?', 'Only if the vendor expressly includes it. Ask about labour charges, the installer, appointment arrangements and how installation affects any warranty. Agree who will check compatibility before the part is fitted.'),
    FaqEntry('return-wrong-part', 'What if a part is wrong, damaged or different from the listing?', 'Keep the packaging, receipt, listing and photographs showing the issue. Contact the vendor promptly and avoid fitting or altering a disputed part before getting advice. The appropriate remedy depends on the facts, the stated terms and your applicable consumer rights.'),
    FaqEntry('join-parts-vendor', 'How can I sell parts on GreenRev?', 'Register using the parts-vendor or relevant business option shown. Describe each item accurately, including brand, part number, condition, compatibility information and price. Confirm the launch package and listing allowance available to your business with support.'),
  ]),
  FaqCategory('mechanics', 'Mechanics and experts', [
    FaqEntry('find-mechanic', 'How do I find a mechanic or automotive expert?', 'Open the experts section and review the providers listed for your location or service need. Check the profile and contact the provider to confirm its specialism, availability, workshop location and charges.'),
    FaqEntry('location-permission', 'Why does a nearby-provider search ask for my location?', 'Location access can help show providers near you. Allow it only if you want to use that feature. If you prefer not to share your location, use a manual location option where available or browse the provider information shown.'),
    FaqEntry('mechanic-distance', 'Does a nearby mechanic result mean the provider is available now?', 'No. A nearby result indicates a location match, not a confirmed appointment or live availability. Contact the provider before travelling and confirm the service location and a suitable time.'),
    FaqEntry('mechanic-booking', 'Does contacting a mechanic create a confirmed booking?', 'At launch, GreenRev helps you discover and contact providers. Agree the appointment, scope of work and price directly with the mechanic. Treat the appointment as confirmed only after the provider accepts it.'),
    FaqEntry('mechanics-employees', 'Are listed mechanics GreenRev employees?', 'Listed mechanics and experts generally operate independently. Confirm who will carry out the work, where it will happen and which business is responsible for the service. The provider profile is a starting point for that conversation.'),
    FaqEntry('mechanic-quote', 'How do I get a repair or service quote?', 'Describe the vehicle and the problem to the provider. Ask whether inspection or diagnosis has a separate fee and request a written estimate separating labour, parts and other charges. Agree how any additional work will be authorised.'),
    FaqEntry('mobile-mechanic', 'Can I request a mobile mechanic or roadside visit?', 'Ask the individual provider whether it offers visits and can attend your location. Confirm call-out fees and availability before agreeing. GreenRev\'s directory is not an emergency-response or guaranteed roadside-recovery service.'),
    FaqEntry('choose-mechanic', 'What should I check before choosing a mechanic?', 'Ask about experience with your vehicle, relevant qualifications, diagnostic equipment and the work proposed. Confirm the workshop or service address, quotation and any workmanship warranty. Reviews or profile information should be considered alongside these checks.'),
    FaqEntry('repair-warranty', 'Who is responsible for a repair warranty or repeat fault?', 'Discuss the workmanship and parts warranty directly with the provider before work begins. If a fault returns, contact that provider with the invoice and agreed scope of work. Report concerns about a GreenRev-listed provider to support with the relevant evidence.'),
    FaqEntry('join-mechanic', 'How can I list my mechanic or expert services?', 'Use the relevant service-provider registration option and describe your business accurately. Include your location, service area, specialisms and reliable contact details. Contact support about the launch package available for your provider category.'),
  ]),
  FaqCategory('fees', 'Fees, packages and payments', [
    FaqEntry('how-greenrev-earns', 'How does GreenRev make money?', 'GreenRev may charge businesses for seller packages, listing exposure and clearly agreed commercial services. The specific offer and price should be confirmed before a business pays. Browsing the marketplace does not commit a customer to buy anything.'),
    FaqEntry('business-account-cost', 'How much does a business package cost?', 'Contact support@greenrevs.com for the launch offer available to your business category. Before paying, confirm the price, package duration, listing allowance, included benefits and any renewal terms in writing.'),
    FaqEntry('listing-limit', 'How many listings can I publish?', 'Your allowance depends on the package available to your account. Check the allowance shown or confirm it with support before publishing a large inventory. Do not assume that a business account includes unlimited listings.'),
    FaqEntry('promoted-listings', 'Can I pay to promote a listing or business?', 'Contact support to ask which promotional placements are available at launch. Agree the placement, duration, price and any delivery commitment before paying. A paid placement does not by itself guarantee enquiries or a sale.'),
    FaqEntry('sponsored-result', 'Does a promoted listing mean the seller or vehicle is better?', 'Promotion is paid visibility. It does not establish that a vehicle, product or provider is safer, better or more suitable for you. Review the listing and carry out the same checks you would for any other result.'),
    FaqEntry('how-payments-work', 'How do payments work at launch?', 'Buyers arrange payment directly with the seller or service provider after agreeing the transaction. GreenRev does not collect the vehicle purchase price, hold marketplace purchase funds or provide escrow at launch. Any GreenRev business-package payment is a separate charge.'),
    FaqEntry('payment-methods', 'Which payment methods can I use for a purchase?', 'Confirm the accepted methods directly with the seller or provider. Verify the recipient and agreed amount before paying, and retain the receipt. GreenRev does not currently offer a shared marketplace checkout or an approved payment link for customer purchases.'),
    FaqEntry('pay-greenrev-fee', 'How should I pay a GreenRev business-package fee?', 'Request the official offer and payment instructions through support@greenrevs.com. Check the package details and confirm the recipient before paying. Do not rely on payment instructions from an unverified social-media account or someone claiming to be an agent.'),
    FaqEntry('renew-cancel-package', 'How do I renew, change or stop a business package?', 'Review the terms supplied with your package and contact support before its renewal or expiry date. Confirm the effective date of any change and what happens to existing listings. Do not assume renewal or cancellation is automatic unless your offer explicitly says so.'),
    FaqEntry('sales-commission', 'Does GreenRev charge a commission on a sale or service?', 'A commission applies only where it is part of the commercial terms agreed with the relevant business. Confirm what triggers it, how it is calculated and when it becomes payable. Do not assume a universal percentage applies to every marketplace transaction.'),
  ]),
  FaqCategory('safety', 'Safety and verification', [
    FaqEntry('verified-badge', 'What does a verification label mean?', 'If a verification label is displayed, read the explanation of the specific check behind it. An identity or business check is different from a vehicle inspection or ownership check. A label alone is not a guarantee of a successful transaction.'),
    FaqEntry('every-car-inspected', 'Has GreenRev physically inspected every listed car?', 'Do not assume that every vehicle has been inspected. Ask for the report, date, scope and inspector if an inspection is claimed. Arrange your own appropriate checks before relying on a listing or inspection statement.'),
    FaqEntry('safe-buying', 'How can I reduce the risk of a fraudulent listing?', 'Verify the seller\'s identity and business, inspect the actual item, compare the documents and get the agreement in writing. Be cautious about unusually low prices, pressure to pay immediately, changing bank details or refusal to allow a reasonable inspection.'),
    FaqEntry('payment-recipient', 'What should I check before transferring money?', 'Check that the recipient is the seller or another party whose authority has been properly explained and documented. Reconfirm bank-detail changes through a trusted contact route. If the recipient name or explanation is inconsistent, pause until the issue is resolved.'),
    FaqEntry('verification-fee-request', 'A seller has asked me for a viewing or verification fee. What should I do?', 'Ask exactly what the charge covers, who receives it and whether it is refundable. Verify the seller and the offer independently before paying. Contact support if someone presents an unexplained charge as a compulsory GreenRev fee.'),
    FaqEntry('keep-codes-private', 'Should I share my password or one-time code with a seller?', 'No. Keep your password, sign-in codes, card PIN and banking authorisation codes private. A seller does not need them to answer an enquiry or sell you an item. If you shared a sensitive code, secure the affected account and contact the relevant provider promptly.'),
    FaqEntry('suspicious-message', 'How can I recognise a suspicious message claiming to be from GreenRev?', 'Be cautious if a message pressures you to pay, asks for a password or code, or sends you to an unfamiliar sign-in page. Open GreenRev independently and contact support@greenrevs.com to verify a doubtful request. A familiar name or logo is not enough.'),
    FaqEntry('report-listing', 'How do I report a suspicious listing or user?', 'Use a report option if one is shown, or email support@greenrevs.com with the listing link, account name and your reason for concern. Include useful screenshots or transaction evidence and avoid sending unnecessary sensitive information.'),
    FaqEntry('stolen-counterfeit-items', 'Can stolen vehicles, counterfeit parts or misleading listings be advertised?', 'No. Advertise only items you have authority to offer and describe them truthfully. If you believe an item is stolen, counterfeit or materially misrepresented, stop the transaction and report your concern with evidence. Contact the relevant authorities where appropriate.'),
    FaqEntry('government-verification', 'Does a listing mean the vehicle has been verified by FRSC or another authority?', 'No. Being listed on GreenRev does not establish government approval or a complete ownership, insurance or vehicle-history check. Use the appropriate official or professional channels to verify the records that matter to your purchase.'),
  ]),
  FaqCategory('issues', 'Problems, returns and complaints', [
    FaqEntry('seller-no-response', 'What if a seller does not respond to my enquiry?', 'Try the other contact option on the listing and allow the business a reasonable opportunity to reply. If the contact details appear wrong or the listing seems inactive, report it to support. Do not send money simply to get a response.'),
    FaqEntry('price-changed', 'What if the price changes after I enquire?', 'Ask the seller to explain the change and obtain a written total before agreeing to proceed. Keep any earlier quotation or agreement. Report a listing if you believe the advertised price was deliberately misleading.'),
    FaqEntry('cancel-purchase', 'Can I cancel a vehicle, part or service arrangement?', 'Contact the seller or provider promptly and refer to the terms you agreed. Cancellation rights and any valid charges depend on the transaction and applicable consumer protections. Keep evidence of when you asked to cancel and the response you received.'),
    FaqEntry('refund-request', 'How do I request a refund?', 'Contact the business that received your payment and explain the issue with supporting evidence. For a GreenRev package fee, contact GreenRev support. Marketplace-purchase refunds are not automatic at launch, and your applicable consumer rights remain unaffected.'),
    FaqEntry('refund-timing', 'How long does a refund take?', 'Ask the party handling the refund for its decision, expected timing and payment reference. The time can depend on the seller, bank or payment provider. GreenRev cannot promise a single refund deadline for payments made directly to independent businesses.'),
    FaqEntry('deposit-dispute', 'What if a seller refuses to return my deposit?', 'Keep the deposit terms, receipt, listing and conversation records. Ask the seller to explain the refusal in writing. You can report the issue to GreenRev for review of the marketplace account and seek help from the relevant payment provider, consumer authority or adviser.'),
    FaqEntry('greenrev-dispute-role', 'Can GreenRev help with a dispute?', 'You can send the listing and relevant evidence to support for review. GreenRev can consider concerns about platform use and seek information from the parties. A support review does not guarantee recovery of money or replace the remedies available through your bank, regulator or the courts.'),
    FaqEntry('complaint-evidence', 'What should I include when making a complaint?', 'Provide your account contact, the listing link, business name, a clear timeline and the outcome you are seeking. Add relevant receipts, quotations and screenshots. Redact unrelated account balances, identity numbers and other information that is not needed to understand the issue.'),
    FaqEntry('suspected-fraud-after-payment', 'What should I do if I suspect fraud after paying?', 'Contact your bank or payment provider immediately to ask what action is available. Preserve the recipient details, receipt, listing and messages, and report the account to GreenRev. Consider reporting the incident to the appropriate law-enforcement authority.'),
    FaqEntry('greenrev-service-complaint', 'How do I complain about a GreenRev package or support decision?', 'Email support@greenrevs.com with the offer or case reference, what happened and the outcome you want. Ask for a review and include any missing evidence. Keep a copy of your complaint and any response; using support does not remove your applicable legal rights.'),
  ]),
  FaqCategory('privacy', 'Privacy and technical help', [
    FaqEntry('privacy-information', 'Where can I find information about my personal data?', 'Read the GreenRev Privacy Policy for information about the data used by the platform, its purposes and the choices available to you. You can raise a privacy question or request through support@greenrevs.com.'),
    FaqEntry('public-documents', 'Should I upload my ID or vehicle documents to a public listing?', 'Avoid publishing full identity documents, bank details, home addresses or unredacted ownership documents in listing photos. Share only what is necessary through an appropriate channel after checking the recipient. Ask support if you are unsure whether a requested upload is private.'),
    FaqEntry('location-control', 'Can I turn off location access?', 'You can manage location permission in your browser or device settings. Turning it off may affect nearby-provider results. Use a manual location option where available, or contact a provider using the information on its profile.'),
    FaqEntry('data-request', 'How do I request access to or correction of my personal data?', 'Email support@greenrevs.com with a clear description of your request and the account it concerns. GreenRev may need to confirm your identity before acting. The Privacy Policy explains relevant rights, conditions and the handling of requests.'),
    FaqEntry('security-concern', 'What if I think someone has accessed my account?', 'Reset your password if possible and secure the email or phone account used for sign-in. Stop sharing any active codes and contact support with details of the suspicious activity. Contact your bank separately if payment information or banking access may be affected.'),
    FaqEntry('page-not-loading', 'What if a GreenRev page does not load correctly?', 'Check your connection, refresh the page and try an up-to-date browser. If the issue continues, note the page link, device and browser, then send support a screenshot or description. Avoid including passwords or other sensitive details in screenshots.'),
    FaqEntry('upload-fails', 'What should I do if an image or listing upload fails?', 'Check any file type, size or required-field message shown on the page. Try a smaller clear image and a stable connection, then review whether the draft was saved before resubmitting. Contact support with the error message if the problem continues.'),
    FaqEntry('map-not-working', 'Why is the map or nearby search showing the wrong location?', 'Check your device location permission and the location entered in your search. Network-based location can be approximate, and provider addresses can change. Confirm the address directly with the business before travelling and report an incorrect profile location.'),
    FaqEntry('contact-button-not-working', 'What if a call, WhatsApp or contact button does not work?', 'Check whether your device has the relevant app and permission to open the link. Try another contact option shown on the profile. Report the listing link and the button that failed to support so the problem can be investigated.'),
    FaqEntry('terms-and-faq', 'Where can I read the rules for using GreenRev?', 'Read the Terms of Use and Privacy Policy linked on GreenRev, together with any specific business offer or seller agreement that applies. This FAQ provides practical guidance and does not replace those documents or remove mandatory consumer rights.'),
  ]),
  FaqCategory('availability', 'Features and availability', [
